// Smoke check: demo.html loads in headless Chrome and the board resizes via ResizeObserver.
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';

const ROOT = 'D:/dev/ab-tasks/chessground-qwen-r2';
const TMP = 'C:/Users/lokta/AppData/Local/Temp/cg-demo-check';
const PORT = 8123;
const CDP_PORT = 9223;
const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const failures = [];
const ok = (name, cond, extra = '') => {
  console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}${extra ? '  [' + extra + ']' : ''}`);
  if (!cond) failures.push(name);
};

// --- static file server for the repo
const MIME = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.map': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
};
const server = createServer(async (req, res) => {
  try {
    const p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    const file = normalize(join(ROOT, p === '/' ? '/demo.html' : p));
    if (!file.startsWith(ROOT)) throw new Error('traversal');
    res.writeHead(200, { 'content-type': MIME[extname(file)] || 'application/octet-stream' });
    res.end(await readFile(file));
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

// --- launch headless chrome
const chrome = spawn(
  CHROME,
  [
    '--headless=new',
    `--remote-debugging-port=${CDP_PORT}`,
    `--user-data-dir=${TMP}/profile`,
    '--no-first-run',
    '--no-default-browser-check',
    '--window-size=1000,900',
    'about:blank',
  ],
  { stdio: 'ignore' },
);

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function waitForTarget() {
  for (let i = 0; i < 150; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json`)).json();
      const t = list.find(t => t.type === 'page');
      if (t) return t;
    } catch {}
    await sleep(100);
  }
  throw new Error('CDP target never appeared');
}

const target = await waitForTarget();
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => {
  ws.addEventListener('open', res, { once: true });
  ws.addEventListener('error', () => rej(new Error('ws connect failed')), { once: true });
});

let seq = 0;
const pending = new Map();
const exceptions = [];
const consoleErrors = [];
const loaded = new Promise(res => {
  ws.addEventListener('message', ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id) {
      pending.get(msg.id)?.(msg);
      pending.delete(msg.id);
    } else if (msg.method === 'Page.loadEventFired') res();
    else if (msg.method === 'Runtime.exceptionThrown')
      exceptions.push(msg.params.exceptionDetails.exception?.description || JSON.stringify(msg.params.exceptionDetails));
    else if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error')
      consoleErrors.push(msg.params.args.map(a => a.value ?? a.description).join(' '));
  });
});
const send = (method, params = {}) =>
  new Promise(res => {
    const id = ++seq;
    pending.set(id, res);
    ws.send(JSON.stringify({ id, method, params }));
  });
const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true })).result;

await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });
await Promise.race([loaded, sleep(15000)]);
await sleep(500); // let module script + rAF settle

// --- 1. load checks
const load = await evaluate(`(() => {
  const boards = [...document.querySelectorAll('.cg-board')];
  const out = {
    boards: boards.length,
    piecesPerBoard: boards.map(b => b.querySelectorAll('.piece').length),
    containers: [...document.querySelectorAll('.cg-container')].map(c => c.style.width + 'x' + c.style.height),
    shapes: document.querySelectorAll('.cg-shapes path, .cg-shapes g > *').length,
    roSupported: 'ResizeObserver' in window,
    dpr: window.devicePixelRatio,
  };
  return out;
})()`);
ok('page has no uncaught exceptions', exceptions.length === 0, exceptions.slice(0, 2).join(' | '));
ok('page has no console errors', consoleErrors.length === 0, consoleErrors.slice(0, 2).join(' | '));
ok('all 5 boards rendered', load.value.boards === 5, `got ${load.value.boards}`);
ok('board-1 has 32 pieces', load.value.piecesPerBoard?.[0] === 32, JSON.stringify(load.value.piecesPerBoard));
ok('board-2 fen has 31 pieces (one pawn missing)', load.value.piecesPerBoard?.[1] === 31, `got ${load.value.piecesPerBoard?.[1]}`);
ok('auto shapes rendered on board-3', load.value.shapes > 0, `got ${load.value.shapes}`);
ok('ResizeObserver available', load.value.roSupported === true);

const floor8 = (x, dpr) => (Math.floor((x * dpr) / 8) * 8) / dpr;
const expectedW = floor8(500, load.value.dpr);
ok(
  'initial container sized from 500px wrap',
  load.value.containers?.every(c => c === `${expectedW}px x ${expectedW}px`),
  JSON.stringify(load.value.containers),
);

// --- 2. resize check: shrink wrap-1, RO must fire and resizes must follow
const before = await evaluate(`(() => {
  const c = document.querySelector('#board-1 .cg-container');
  return c.getBoundingClientRect().width;
})()`);
await evaluate(`document.getElementById('board-1').style.cssText = 'width:300px;height:300px'`);
await sleep(400); // RO callback + layout
const after = await evaluate(`(() => {
  const c = document.querySelector('#board-1 .cg-container');
  return { styleW: c.style.width, rectW: c.getBoundingClientRect().width };
})()`);
const expectedAfter = floor8(300, load.value.dpr);
ok('container width changed after resize', after.value.rectW !== before.value, `${before.value} -> ${after.value.rectW}`);
ok('container follows new wrap size (RO fired)', after.value.styleW === `${expectedAfter}px`, `style=${after.value.styleW} expected=${expectedAfter}px`);

// grow it back: 700px
await evaluate(`document.getElementById('board-1').style.cssText = 'width:700px;height:700px'`);
await sleep(400);
const grown = await evaluate(`document.querySelector('#board-1 .cg-container').style.width`);
ok('container follows grow to 700px wrap', grown.value === `${floor8(700, load.value.dpr)}px`, `got ${grown.value}`);

// --- screenshot as evidence
const shot = await send('Page.captureScreenshot', { format: 'png' });
await (await import('node:fs/promises')).writeFile(`${TMP}/demo.png`, Buffer.from(shot.data, 'base64'));
console.log(`screenshot: ${TMP}/demo.png`);

ok('still no uncaught exceptions at end', exceptions.length === 0, exceptions.slice(0, 2).join(' | '));

ws.close();
chrome.kill();
server.close();
console.log(failures.length === 0 ? '\nDEMO CHECK: ALL PASS' : `\nDEMO CHECK: ${failures.length} FAILURES: ${failures.join('; ')}`);
process.exit(failures.length === 0 ? 0 : 1);

